import{z as p,x as A,o as i,c as d,q as s,j as r,D as t,d as n,s as l,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"命题逻辑与范式","description":"","frontmatter":{"title":"命题逻辑与范式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/propositional-logic-cnf.md","filePath":"cs/propositional-logic-cnf.md","lastUpdated":1791413859000}'),C={name:"cs/propositional-logic-cnf.md"};function F(B,a,c,T,N,D){const o=A("Mermaid");return i(),d("div",null,[a[2]||(a[2]=s('<h1 id="命题逻辑与范式" tabindex="-1">命题逻辑与范式 <a class="header-anchor" href="#命题逻辑与范式" aria-label="Permalink to &quot;命题逻辑与范式&quot;">​</a></h1><div class="epigraph"><p>命题公式由原子与连接词建成；语义是赋值到 $\\{0,1\\}$。CNF 把可满足性收成子句集合，Tseitin 变换多项式保持可满足，不必指数展开。</p><footer>—— 据 Enderton, A Mathematical Introduction to Logic；Tseitin, 1968 整理</footer></div><p>数论单元在<a href="/cs/lattice-lwe">LWE</a> 结束。逻辑单元从公式起。<a href="/cs/boolean-algebra">布尔代数</a> 已给与或非公理；主干<a href="/cs/sat-3sat">SAT 与 3-SAT</a> 已把 CNF 当 NP 对象。缺口是<strong>作为证明系统的命题逻辑</strong>：语法、语义、NNF/CNF，以及「等价变换」与「等可满足」的差别。后课量词、自然演绎默认已读完本课的公式层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原子 \\(P,Q,\\ldots\\)，连接 \\(\\neg,\\land,\\lor,\\to\\)。赋值 \\(v\\)，归纳定义 \\(v(\\varphi)\\in\\{0,1\\}\\)。重言式：一切 \\(v\\) 为真；可满足：存在 \\(v\\)。CNF：子句合取；DNF：项析取。把任意公式展成等价 CNF 可指数（分配律）。Tseitin：给每个子公式新变元，加表示「新变元 \\(\\leftrightarrow\\) 子公式」的常数个子句，<strong>等可满足</strong>、规模线性。SAT 求解用后者。</p><p><a href="/cs/cook-levin">Cook–Levin</a> 的表格产出的已是 CNF 形状；本课给手工公式一条进 CNF 的路。</p><h3 id="范式不是化简" tabindex="-1">范式不是化简 <a class="header-anchor" href="#范式不是化简" aria-label="Permalink to &quot;范式不是化简&quot;">​</a></h3><p>卡诺图、Quine–McCluskey 求最短与或式，对象是电路代价。本课 CNF 为判定与归结服务，子句可以多。</p><p><span class="marginnote">Enderton 命题章。Tseitin 1968 对扩充归结。Davis–Putnam 时代已用 CNF。本课不跑 DPLL——那是本单元后部。</span></p><p><span class="marginnote">初学者容易以为 CNF 是「更简单的形状」。实际上用分配律硬展开，公式可能膨胀得比原式大得多；CNF 的好处不是短，而是「子句合取」正好是求解器数据结构爱吃的形状。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写一份含 \\(\\to\\) 的公式，先去 \\(\\to\\)，再 NNF，再 Tseitin 而不暴力分配。强调：重言式判定 coNP（UNSAT）；可满足 NP。真值表指数，不是算法出路。</p>',12)),(i(),r(E,null,{default:t(()=>[l(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FML%5B%22%E5%91%BD%E9%A2%98%E5%85%AC%E5%BC%8F%22%5D%20--%3E%20SEM%5B%22%E8%B5%8B%E5%80%BC%E8%AF%AD%E4%B9%89%22%5D%0A%20%20FML%20--%3E%20TSE%5B%22Tseitin%20CNF%22%5D%0A%20%20TSE%20--%3E%20SAT%5B%22%E7%AD%89%E5%8F%AF%E6%BB%A1%E8%B6%B3%20SAT%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了 CNF，归结、CDCL 才有子句数据库。完备性下一课仍对自然演绎，对象可先是任意公式。本课不引入量词：命题没有「对所有整数」。",-1)),a[5]||(a[5]=e("p",null,"布尔代数的等价变形保持语义相等；Tseitin 只保持可满足，多出来的变元无原公式对应。",-1)),a[6]||(a[6]=e("p",null,"紧致性：无限命题集合可满足当且仅当每个有限子集可满足——后课不用。归结对 CNF 反驳完备，CDCL 是其工程后代。Tseitin 增加的变元必须被约束到子公式真值，否则 SAT 会「借假变元」满足。与布尔化简课分工：那里最短式，这里判定。",-1)),(i(),r(E,null,{default:t(()=>[l(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%8E%9F%E5%85%AC%E5%BC%8F%20P%20%E4%B8%8E%20Q%22%5D%20--%3E%20X%5B%22%E5%BC%95%E5%85%A5%E6%96%B0%E5%8F%98%E5%85%83%20X%20%E4%BB%A3%E8%A1%A8%E6%95%B4%E4%B8%AA%E5%AD%90%E5%85%AC%E5%BC%8F%22%5D%0A%20%20X%20--%3E%20C1%5B%22%E5%AD%90%E5%8F%A5%20%E9%9D%9EX%20%E6%88%96%20P%22%5D%0A%20%20X%20--%3E%20C2%5B%22%E5%AD%90%E5%8F%A5%20%E9%9D%9EX%20%E6%88%96%20Q%22%5D%0A%20%20X%20--%3E%20C3%5B%22%E5%AD%90%E5%8F%A5%20X%20%E6%88%96%20%E9%9D%9EP%20%E6%88%96%20%E9%9D%9EQ%22%5D%0A%20%20C1%20--%3E%20S%7B%22%E5%90%88%E5%8F%96%E4%B8%89%E5%AD%90%E5%8F%A5%E6%B1%82%20SAT%22%7D%0A%20%20C2%20--%3E%20S%0A%20%20C3%20--%3E%20S%0A%20%20S%20--%3E%7C%22X%20%E5%8F%AF%E5%8F%96%201%22%7C%20Y%5B%22%E5%8E%9F%E5%85%AC%E5%BC%8F%E5%8F%AF%E6%BB%A1%E8%B6%B3%22%5D%0A%20%20S%20--%3E%7C%22X%20%E5%8F%AA%E8%83%BD%E5%8F%96%200%22%7C%20N%5B%22%E5%8E%9F%E5%85%AC%E5%BC%8F%E4%B8%8D%E5%8F%AF%E6%BB%A1%E8%B6%B3%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">上图回答「Tseitin 到底加了什么」：每个子公式领一个新变元 \\(X\\)，再用常数条子句钉死 \\(X \\leftrightarrow (P \\land Q)\\)。\\(X\\) 若想取 1，就得真有 \\(P\\)、\\(Q\\) 同真——这就是「不会借假变元满足」的原因。</span></p><p><span class="marginnote">「等可满足」就是「要么都可有真赋值、要么都不行」，但不保证变元取值一一对应：新变元 \\(X\\) 是占位符，求出满足赋值后把它的值回读出来，才是原公式的真值安排。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证紧致性，不引入模态。不重做 3-SAT 拆句。后课默认：公式有语法树与赋值；进求解器走 Tseitin CNF。下一课谓词与量词。</p><p>真等价的 CNF 可指数；SAT 求解用 Tseitin 等可满足。可满足 NP、重言 coNP，真值表不是算法。后课量词把赋值从 \\(2^n\\) 换成可能无穷的论域。</p><p><span class="marginnote">给个数的感觉：一个 30 个变元的公式，真值表要列 \\(2^{30} \\approx 10\\) 亿行；Tseitin 只对每个子公式加一个变元、约 3 条子句，规模与公式长度成正比——这就是「指数对线性」的差距。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>命题：语法 + 赋值语义；CNF 是子句合取。</li><li>Tseitin 多项式等可满足，真等价 CNF 可指数。</li><li>可满足 NP，重言 coNP；真值表不是出路。</li><li>出处：Enderton；Tseitin, 1968。</li></ul>',8))])}const f=p(C,[["render",F]]);export{m as __pageData,f as default};
